input.sparql:
SELECT ?s ?name ?iri WHERE {
  ?s a brick:Air_Handling_Unit .
  ?s rdfs:label ?name .
  FILTER (CONTAINS(?name, "AHU03") || ?name = "AHU03")
} LIMIT 20

SELECT ?s ?name ?iri ?class WHERE {
  ?s a ?class .
  ?s rdfs:label ?name .
  FILTER (CONTAINS(?name, "03"))
} LIMIT 40

SELECT ?s ?name WHERE {
  ?s rdfs:label ?name .
  FILTER (CONTAINS(LCASE(STR(?s)), "ahU03") || CONTAINS(LCASE(STR(?s)), "ahu_03") || CONTAINS(LCASE(STR(?s)), "ahu03"))
} LIMIT 40
